import zlib, base64, os

files = {}
files["/home/ubuntu/finance-knowledge-engine/frontend/src/components/Sidebar/Sidebar.jsx"] = ""
files["/home/ubuntu/finance-knowledge-engine/frontend/src/components/Sidebar/Sidebar.module.css"] = ""

for path, b64_content in files.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    data = zlib.decompress(base64.b64decode(b64_content))
    with open(path, "wb") as f:
        f.write(data)
    print(f"Updated: {path} ({len(data)} bytes)")
print("SIDEBAR HOVER & DOTS CONTRAST FIX APPLIED!")
